-- Run this whole file in Supabase SQL Editor.
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
create or replace function public.admin_get_coachings() returns table(id uuid,owner_id uuid,owner_email text,coaching_name text,slug text,description text,logo_url text,founder_name text,founder_designation text,founder_photo_url text,phone text,email text,address text,created_at timestamptz,updated_at timestamptz) language plpgsql security definer set search_path=public,auth as $$ begin if not public.is_admin() then raise exception 'Admin access required'; end if; return query select c.id,c.owner_id,u.email::text,c.coaching_name,c.slug,c.description,c.logo_url,c.founder_name,c.founder_designation,c.founder_photo_url,c.phone,c.email,c.address,c.created_at,c.updated_at from public.coachings c left join auth.users u on u.id=c.owner_id order by c.created_at desc; end; $$;
create or replace function public.admin_delete_owner(target_user_id uuid) returns boolean language plpgsql security definer set search_path=public,auth as $$ begin if not public.is_admin() then raise exception 'Admin access required'; end if; if target_user_id=auth.uid() then raise exception 'Cannot delete your own admin account'; end if; delete from auth.users where id=target_user_id; return found; end; $$;
revoke all on function public.admin_get_coachings() from public; grant execute on function public.admin_get_coachings() to authenticated;
revoke all on function public.admin_delete_owner(uuid) from public; grant execute on function public.admin_delete_owner(uuid) to authenticated;
